style.css:
/* SHADOW BOY — Roblox */

:root {
  /* swap these colours if you want */
  --my-bg: #080808;
  --my-panel: #151515;
  --my-card: #202020;
  --my-accent: #c8c8c8;
  --my-text: #eeeeee;
  --my-muted: #888888;
}

/* dark background */
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* panels and cards */
[role="main"],
[role="navigation"],
section,
main {
  color: var(--my-text) !important;
}

/* links */
a {
  color: var(--my-accent) !important;
  transition: 0.2s ease !important;
}

a:hover {
  color: white !important;
}

/* buttons */
button {
  background: var(--my-card) !important;
  color: white !important;
  border: 1px solid #444 !important;
  border-radius: 10px !important;
  transition: 0.2s ease !important;
}

button:hover {
  background: #383838 !important;
  border-color: white !important;
}

/* images */
img {
  border-radius: 8px;
}

/* input boxes */
input {
  background: #171717 !important;
  color: white !important;
  border: 1px solid #444 !important;
  border-radius: 8px !important;
}

/* scrollbars */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-thumb {
  background: #555;
  border-radius: 10px;
}

::-webkit-scrollbar-track {
  background: #080808;
}
